count = var.deploy_application ? 1 : 0
zone_id = var.origin_zone_id
name = var.origin_hostname
type = "A"
lifecycle {
  precondition {
    condition = module.alb[0].listener_rule_arn != null
    error_message = "Publish origin DNS only after the HTTPS forwarding rule is ready."
  }
}
alias {
  name = module.alb[0].dns
  zone_id = module.alb[0].zone_id
  evaluate_target_health = true
}

load_balancer_arn = aws_lb.this.arn
protocol          = "HTTPS"
port              = 443
ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
certificate_arn   = var.certificate_arn

default_action {
  type             = "fixed-response"
  fixed_response {
    content_type = "text/plain"
    message_body = "Origin access required"
    status_code  = "403"
  }
}

listener_arn = aws_lb_listener.https.arn
priority = 10
action {
  type = "forward"
  target_group_arn = aws_lb_target_group.backend.arn
}
condition {
  http_header {
    http_header_name = "X-ClimateHealth-Origin"
    values = [var.origin_header]
  }
}

for_each             = toset(var.ecr_names)
lifecycle { prevent_destroy = true }
name                 = each.value
image_tag_mutability = "IMMUTABLE"

image_scanning_configuration {
  scan_on_push = true
}

encryption_configuration {
  encryption_type = "AES256"
}

