blocks.body:
name = "backend"
cluster = aws_ecs_cluster.this.id
task_definition = aws_ecs_task_definition.initial.arn
desired_count = var.desired_count
deployment_minimum_healthy_percent = var.max_instances > 1 ? 100 : 0
deployment_maximum_percent = var.max_instances > 1 ? 200 : 100
health_check_grace_period_seconds = 90
enable_execute_command = false
wait_for_steady_state = true
timeouts {
  create = "20m"
  update = "20m"
}
deployment_circuit_breaker {
  enable = true
  rollback = true
}
capacity_provider_strategy {
  capacity_provider = aws_ecs_capacity_provider.host.name
  weight = 1
}
load_balancer {
  target_group_arn = var.target_group_arn
  container_name = "backend"
  container_port = 8000
}
depends_on = [aws_ecs_cluster_capacity_providers.this, aws_iam_role_policy.execution, aws_autoscaling_group.host]
# HCP owns task configuration for the first controlled deployment. CD remains disabled.
lifecycle {
  precondition {
    condition = var.listener_rule_arn != null
    error_message = "Wait for the HTTPS listener rule before associating this target group."
  }
}

for_each = local.buckets
bucket = each.value
versioning_configuration { status = "Enabled" }

for_each = local.buckets
bucket = each.value
rule {
  apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
}

for_each = local.buckets
bucket = each.value
rule { object_ownership = "BucketOwnerEnforced" }

name = "${var.name}-assets"
min_ttl = 0
default_ttl = 86400
max_ttl = 31536000
parameters_in_cache_key_and_forwarded_to_origin {
  enable_accept_encoding_gzip = true
  enable_accept_encoding_brotli = true
  cookies_config { cookie_behavior = "none" }
  headers_config { header_behavior = "none" }
  query_strings_config { query_string_behavior = "none" }
}

name = "${var.name}-spa"
runtime = "cloudfront-js-2.0"
publish = true
code = <<-JS
  function handler(event) {
    var request = event.request;
    if (['/', '/dashboard', '/hri', '/map', '/history'].indexOf(request.uri) !== -1) request.uri = '/index.html';
    return request;
  }
JS

enabled = true
default_root_object = "index.html"
price_class = "PriceClass_100"
origin {
  domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
  origin_id = "frontend"
  origin_access_control_id = aws_cloudfront_origin_access_control.this.id
}
dynamic "origin" {
  for_each = var.api_enabled ? [1] : []
  content {
    domain_name = var.origin_hostname
    origin_id = "api"
    custom_header {
      name = "X-ClimateHealth-Origin"
      value = var.origin_header
    }
    custom_origin_config {
      http_port = 80
      https_port = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols = ["TLSv1.2"]
    }
  }
}
default_cache_behavior {
  target_origin_id = "frontend"
  viewer_protocol_policy = "redirect-to-https"
  allowed_methods = ["GET", "HEAD"]
  cached_methods = ["GET", "HEAD"]
  cache_policy_id = data.aws_cloudfront_cache_policy.disabled.id
  compress = true
  function_association {
    event_type = "viewer-request"
    function_arn = aws_cloudfront_function.routes.arn
  }
}
dynamic "ordered_cache_behavior" {
  for_each = var.api_enabled ? [1] : []
  content {
    path_pattern = "/api/*"
    target_origin_id = "api"
    viewer_protocol_policy = "https-only"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "POST", "PUT", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    cache_policy_id = data.aws_cloudfront_cache_policy.disabled.id
    origin_request_policy_id = data.aws_cloudfront_origin_request_policy.api[0].id
    compress = true
  }
}
ordered_cache_behavior {
  path_pattern = "/assets/*"
  target_origin_id = "frontend"
  viewer_protocol_policy = "redirect-to-https"
  allowed_methods = ["GET", "HEAD"]
  cached_methods = ["GET", "HEAD"]
  cache_policy_id = aws_cloudfront_cache_policy.assets.id
  compress = true
}
restrictions {
  geo_restriction { restriction_type = "none" }
}
viewer_certificate { cloudfront_default_certificate = true }

bucket = aws_s3_bucket.frontend.id
policy = jsonencode({ Version = "2012-10-17", Statement = concat([
      { Sid = "CloudFrontOnly", Effect = "Allow", Principal = { Service = "cloudfront.amazonaws.com" }, Action = "s3:GetObject", Resource = "${aws_s3_bucket.frontend.arn}/*", Condition = { StringEquals = { "AWS:SourceArn" = aws_cloudfront_distribution.this.arn } } }
    ], [
      { Sid = "DenyHTTP", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [aws_s3_bucket.frontend.arn,"${aws_s3_bucket.frontend.arn}/*"], Condition = { Bool = { "aws:SecureTransport" = "false" } } }
    ]) })

